-- Help center refresh (2026-11-22): FAQ, seller guide and commissions text updated to the current marketplace
-- (guest cart, delivery country and per-product destinations, shipping/return policies, receipts, payout hold).
-- Explicit es/en/fr/ht. Still editable in Admin → Configuración → Ayuda y redes; publishes a new version.

CREATE OR REPLACE FUNCTION pg_temp.nx_set(p_key text, p_value jsonb, p_only_if jsonb DEFAULT NULL)
RETURNS void LANGUAGE plpgsql AS $$
DECLARE
  v_current jsonb;
  v_id uuid;
  v_actor uuid;
BEGIN
  SELECT value INTO v_current FROM public.system_setting_values
   WHERE setting_key = p_key AND scope_type = 'GLOBAL' AND status = 'ACTIVE'
   ORDER BY version_number DESC LIMIT 1;
  IF v_current IS NOT NULL AND (v_current = p_value OR (p_only_if IS NOT NULL AND v_current <> p_only_if)) THEN
    RETURN; -- unchanged, or customised by an operator: keep it
  END IF;
  SELECT u.id INTO v_actor FROM public.users u
    JOIN public.user_roles ur ON ur.user_id = u.id JOIN public.roles r ON r.id = ur.role_id
   WHERE r.code IN ('SUPER_ADMIN', 'ADMIN') ORDER BY u.created_at LIMIT 1;
  INSERT INTO public.system_setting_values (setting_key, version_number, scope_type, value, checksum, status, created_by_user_id)
  VALUES (p_key, COALESCE((SELECT max(version_number) FROM public.system_setting_values WHERE setting_key = p_key), 0) + 1,
          'GLOBAL', p_value, extensions.digest(p_value::text, 'sha256'), 'DRAFT', v_actor)
  RETURNING id INTO v_id;
  IF v_actor IS NOT NULL THEN
    PERFORM public.activate_system_setting_value(v_id, v_actor, now());
  ELSE
    UPDATE public.system_setting_values SET status = 'SUPERSEDED', superseded_at = now()
     WHERE setting_key = p_key AND scope_type = 'GLOBAL' AND status = 'ACTIVE';
    UPDATE public.system_setting_values SET status = 'ACTIVE', effective_at = now(), activated_at = now() WHERE id = v_id;
    INSERT INTO public.system_setting_history (setting_value_id, event_type, reason) VALUES (v_id, 'ACTIVATED', 'Centro de ayuda actualizado (carrito sin cuenta, destinos, envíos, devoluciones, recibos)');
  END IF;
END $$;

SELECT pg_temp.nx_set('help.faq', $h$[{"q": "¿Cómo compro en NEXOVAX?", "a": "Elige tu país en «Enviar a», agrega productos al carrito (no necesitas una cuenta para eso) y pulsa «Finalizar compra». Para pagar debes iniciar sesión o crear tu cuenta; los productos de tu carrito se conservan. Después eliges la dirección de entrega, el envío de cada tienda y el método de pago.", "qEn": "How do I buy on NEXOVAX?", "aEn": "Choose your country in “Deliver to”, add products to your cart (you don’t need an account for that) and select “Checkout”. To pay you need to sign in or create an account; the products in your cart are kept. Then choose the delivery address, the shipping option for each store and the payment method.", "qFr": "Comment acheter sur NEXOVAX ?", "aFr": "Choisissez votre pays dans « Envoyer à », ajoutez des produits au panier (pas besoin de compte pour cela) et cliquez sur « Paiement ». Pour payer, vous devez vous connecter ou créer un compte ; les produits de votre panier sont conservés. Choisissez ensuite l’adresse de livraison, l’envoi de chaque boutique et le moyen de paiement.", "qHt": "Kijan pou m achte sou NEXOVAX?", "aHt": "Chwazi peyi w nan « Voye bay », mete pwodwi nan panye a (ou pa bezwen yon kont pou sa) epi peze « Peman ». Pou w peye, ou dwe konekte oswa kreye kont ou; pwodwi ki nan panye w yo rete ladan l. Apre sa ou chwazi adrès livrezon an, livrezon chak boutik ak mwayen peman an."}, {"q": "¿Por qué un producto aparece «No disponible» para mi país?", "a": "Cada tienda decide a qué países envía y puede limitarlo producto por producto. Si un producto no se envía al país que elegiste en «Enviar a», aparece como no disponible y no se puede pagar. La disponibilidad final se confirma con la dirección de entrega al pagar.", "qEn": "Why is a product “Not available” for my country?", "aEn": "Each store decides which countries it ships to and can limit this product by product. If a product doesn’t ship to the country you chose in “Deliver to”, it shows as not available and can’t be paid for. Final availability is confirmed with the delivery address at checkout.", "qFr": "Pourquoi un produit est-il « Non disponible » pour mon pays ?", "aFr": "Chaque boutique décide vers quels pays elle expédie et peut le limiter produit par produit. Si un produit n’est pas expédié vers le pays choisi dans « Envoyer à », il apparaît comme indisponible et ne peut pas être payé. La disponibilité finale est confirmée avec l’adresse de livraison au paiement.", "qHt": "Poukisa yon pwodwi parèt « Pa disponib » pou peyi m?", "aHt": "Chak boutik deside nan ki peyi li voye epi li ka limite sa pwodwi pa pwodwi. Si yon pwodwi pa voye nan peyi ou chwazi nan « Voye bay », li parèt pa disponib epi ou pa ka peye l. Disponiblite final la konfime ak adrès livrezon an lè w ap peye."}, {"q": "¿Qué métodos de pago aceptan?", "a": "En el checkout verás los métodos activos: tarjeta de crédito o débito, transferencia bancaria y PayPal cuando está habilitado. Con transferencia reservamos tu inventario hasta 72 horas mientras validamos el pago.", "qEn": "Which payment methods do you accept?", "aEn": "Checkout shows the active methods: credit or debit card, bank transfer and PayPal when it is enabled. With a bank transfer we hold your items for up to 72 hours while we confirm the payment.", "qFr": "Quels moyens de paiement acceptez-vous ?", "aFr": "Le paiement affiche les moyens actifs : carte de crédit ou de débit, virement bancaire et PayPal lorsqu’il est activé. Avec un virement, nous réservons vos articles jusqu’à 72 heures pendant la validation du paiement.", "qHt": "Ki mwayen peman nou aksepte?", "aHt": "Nan peman an w ap wè mwayen ki aktif yo: kat kredi oswa debi, transfè labank ak PayPal lè li aktive. Avèk transfè, nou rezève atik ou yo jiska 72 èdtan pandan n ap valide peman an."}, {"q": "¿Cuánto cuesta el envío y cuánto tarda?", "a": "Depende de la tienda, de tu dirección y del paquete. En el checkout verás las opciones disponibles con su precio y tiempo estimado: tarifas en vivo de las transportadoras cuando la ruta lo permite o las tarifas del marketplace, y retiro en tienda si estás en el mismo país. Las tiendas preparan los pedidos en 1 a 3 días hábiles. Consulta el detalle en la Política de envíos.", "qEn": "How much does shipping cost and how long does it take?", "aEn": "It depends on the store, your address and the package. At checkout you’ll see the available options with their price and estimated time: live carrier rates when the route allows it or the marketplace rates, and store pickup if you’re in the same country. Stores prepare orders in 1 to 3 business days. See the Shipping policy for details.", "qFr": "Combien coûte la livraison et combien de temps prend-elle ?", "aFr": "Cela dépend de la boutique, de votre adresse et du colis. Au paiement, vous verrez les options disponibles avec leur prix et leur délai estimé : tarifs en direct des transporteurs lorsque l’itinéraire le permet ou tarifs du marketplace, et retrait en boutique si vous êtes dans le même pays. Les boutiques préparent les commandes en 1 à 3 jours ouvrables. Consultez la Politique d’expédition pour le détail.", "qHt": "Konbyen livrezon an koute e konbyen tan li pran?", "aHt": "Sa depann de boutik la, adrès ou ak pake a. Nan peman an w ap wè opsyon ki disponib yo ak pri yo ak tan estime: pri an dirèk transpòtè yo lè wout la pèmèt sa oswa pri marketplace la, ak retire nan boutik si w nan menm peyi a. Boutik yo prepare kòmand yo nan 1 a 3 jou ouvrab. Gade detay yo nan Politik livrezon an."}, {"q": "¿Hacen envíos internacionales?", "a": "Sí, a los países disponibles en «Enviar a». Las tiendas despachan desde distintos países y en el checkout verás las opciones para tu dirección. Los impuestos de importación, aranceles y trámites de aduana del país de destino corren por cuenta del comprador, salvo que el checkout indique lo contrario.", "qEn": "Do you ship internationally?", "aEn": "Yes, to the countries available in “Deliver to”. Stores ship from different countries and checkout shows the options for your address. Import taxes, duties and customs fees of the destination country are paid by the buyer, unless checkout says otherwise.", "qFr": "Livrez-vous à l’international ?", "aFr": "Oui, vers les pays disponibles dans « Envoyer à ». Les boutiques expédient depuis différents pays et le paiement affiche les options pour votre adresse. Les taxes d’importation, droits de douane et formalités du pays de destination sont à la charge de l’acheteur, sauf indication contraire au paiement.", "qHt": "Èske nou voye nan lòt peyi?", "aHt": "Wi, nan peyi ki disponib nan « Voye bay ». Boutik yo voye soti nan diferan peyi epi nan peman an w ap wè opsyon pou adrès ou. Taks enpòtasyon, dwa ladwàn ak frè ladwàn peyi destinasyon an se achtè a ki peye yo, sof si peman an di lòt bagay."}, {"q": "¿Cómo se calculan los impuestos?", "a": "Según la dirección de entrega aplicamos el impuesto al consumo que corresponda (sales tax, IVA, VAT, ITBIS…) sobre los productos y, cuando aplica, sobre el envío. Verás el detalle antes de confirmar la compra y también en tu recibo.", "qEn": "How are taxes calculated?", "aEn": "Based on the delivery address we apply the applicable consumption tax (sales tax, VAT, GST, ITBIS…) to the products and, where required, to shipping. You’ll see the breakdown before confirming the purchase and on your receipt.", "qFr": "Comment les taxes sont-elles calculées ?", "aFr": "Selon l’adresse de livraison, nous appliquons la taxe à la consommation applicable (sales tax, TVA, VAT, ITBIS…) aux produits et, le cas échéant, à la livraison. Vous verrez le détail avant de confirmer l’achat ainsi que sur votre reçu.", "qHt": "Kijan nou kalkile taks yo?", "aHt": "Selon adrès livrezon an, nou aplike taks konsomasyon ki koresponn lan (sales tax, TVA, VAT, ITBIS…) sou pwodwi yo e, lè sa aplike, sou livrezon an. W ap wè detay la anvan w konfime acha a epi tou sou resi w la."}, {"q": "¿Cómo sigo mi pedido y dónde está mi recibo?", "a": "En «Mi cuenta → Pedidos» verás el estado, la transportadora, el número de seguimiento y el historial de cada envío; los envíos con etiqueta se actualizan automáticamente. Desde el pedido puedes abrir el recibo de compra, con los datos de la tienda y los descuentos aplicados.", "qEn": "How do I track my order and where is my receipt?", "aEn": "In “My account → Orders” you’ll see the status, carrier, tracking number and history of each shipment; shipments with a label update automatically. From the order you can open the purchase receipt, with the store’s details and any discounts applied.", "qFr": "Comment suivre ma commande et où trouver mon reçu ?", "aFr": "Dans « Mon compte → Commandes », vous verrez le statut, le transporteur, le numéro de suivi et l’historique de chaque envoi ; les envois avec étiquette se mettent à jour automatiquement. Depuis la commande, vous pouvez ouvrir le reçu d’achat, avec les informations de la boutique et les remises appliquées.", "qHt": "Kijan pou m swiv kòmand mwen e ki kote resi m ye?", "aHt": "Nan « Kont mwen → Kòmand » w ap wè eta a, transpòtè a, nimewo swivi a ak istwa chak livrezon; livrezon ki gen etikèt mete tèt yo ajou otomatikman. Depi nan kòmand lan ou ka louvri resi acha a, ak enfòmasyon boutik la ak rabè ki aplike yo."}, {"q": "¿Puedo devolver un producto?", "a": "Sí. Todas las tiendas siguen la misma política: tienes 30 días desde la entrega para solicitar la devolución desde tu pedido. Envías el producto por correo y cubres el envío de vuelta; no cobramos cargo por reposición. Cuando la tienda lo recibe e inspecciona, reembolsamos al mismo método de pago. No hacemos cambios: para otra talla o color, devuelve el producto y haz un pedido nuevo. Consulta la Política de devoluciones.", "qEn": "Can I return a product?", "aEn": "Yes. Every store follows the same policy: you have 30 days from delivery to request a return from your order. You send the product back by mail and pay the return shipping; there is no restocking fee. Once the store receives and inspects it, we refund the original payment method. We don’t do exchanges: for another size or color, return the product and place a new order. See the Return policy.", "qFr": "Puis-je retourner un produit ?", "aFr": "Oui. Toutes les boutiques suivent la même politique : vous avez 30 jours après la livraison pour demander le retour depuis votre commande. Vous renvoyez le produit par la poste et payez le retour ; aucuns frais de remise en stock. Une fois le produit reçu et inspecté par la boutique, nous remboursons le moyen de paiement d’origine. Pas d’échanges : pour une autre taille ou couleur, retournez le produit et passez une nouvelle commande. Consultez la Politique de retour.", "qHt": "Èske m ka retounen yon pwodwi?", "aHt": "Wi. Tout boutik yo swiv menm politik la: ou gen 30 jou apre livrezon an pou mande retou a depi nan kòmand ou. Ou voye pwodwi a pa lapòs epi ou peye livrezon retou a; pa gen frè pou remete an stòk. Lè boutik la resevwa l epi enspekte l, nou ranbouse sou menm mwayen peman an. Nou pa fè echanj: pou yon lòt gwosè oswa koulè, retounen pwodwi a epi fè yon nouvo kòmand. Gade Politik retou a."}, {"q": "¿Cómo vendo en NEXOVAX?", "a": "Crea una cuenta y completa el registro de tu tienda con tu país, tu identificación fiscal y la dirección desde donde despachas. Tu tienda queda activa al instante. Publica tus productos, elige a qué países los envías y empieza a vender; si la administración activa la revisión previa, tus productos se muestran cuando se aprueban.", "qEn": "How do I sell on NEXOVAX?", "aEn": "Create an account and complete your store registration with your country, tax ID and the address you ship from. Your store is active right away. Publish your products, choose which countries you ship them to and start selling; if the administration turns on prior review, your products appear once approved.", "qFr": "Comment vendre sur NEXOVAX ?", "aFr": "Créez un compte et complétez l’inscription de votre boutique avec votre pays, votre identifiant fiscal et l’adresse d’expédition. Votre boutique est active immédiatement. Publiez vos produits, choisissez vers quels pays vous les expédiez et commencez à vendre ; si l’administration active la révision préalable, vos produits s’affichent une fois approuvés.", "qHt": "Kijan pou m vann sou NEXOVAX?", "aHt": "Kreye yon kont epi ranpli enskripsyon boutik ou ak peyi w, idantifyan fiskal ou ak adrès kote w voye pwodwi yo. Boutik ou aktif touswit. Pibliye pwodwi ou yo, chwazi nan ki peyi w voye yo epi kòmanse vann; si administrasyon an aktive revizyon davans, pwodwi ou yo parèt lè yo apwouve."}]$h$::jsonb);
SELECT pg_temp.nx_set('help.sellers', $h${"sections": [{"title": "Registra tu tienda", "body": "Crea una cuenta y completa el registro de tu tienda con tu país, tu identificación fiscal y la dirección desde donde despachas. Tu tienda queda activa al instante; solo verificamos tu cuenta de cobro antes de habilitar retiros. Tu razón social e identificación fiscal aparecen en los recibos de tus ventas.", "titleEn": "Register your store", "bodyEn": "Create an account and complete your store registration with your country, tax ID and the address you ship from. Your store is active right away; we only verify your payout account before enabling withdrawals. Your legal name and tax ID appear on the receipts of your sales.", "titleFr": "Inscrivez votre boutique", "bodyFr": "Créez un compte et complétez l’inscription de votre boutique avec votre pays, votre identifiant fiscal et l’adresse d’expédition. Votre boutique est active immédiatement ; nous vérifions seulement votre compte de versement avant d’activer les retraits. Votre raison sociale et votre identifiant fiscal figurent sur les reçus de vos ventes.", "titleHt": "Enskri boutik ou", "bodyHt": "Kreye yon kont epi ranpli enskripsyon boutik ou ak peyi w, idantifyan fiskal ou ak adrès kote w voye pwodwi yo. Boutik ou aktif touswit; nou verifye sèlman kont peman w anvan nou pèmèt retrè. Non legal ou ak idantifyan fiskal ou parèt sou resi vant ou yo."}, {"title": "Publica tus productos", "body": "Agrega fotos, descripción, atributos, variantes, precio, inventario y medidas del paquete. Al publicar, el producto aparece en el catálogo al instante, salvo que la administración tenga activa la revisión previa: en ese caso se muestra cuando se aprueba, y si editas el contenido de un producto publicado vuelve a revisión.", "titleEn": "Publish your products", "bodyEn": "Add photos, description, attributes, variants, price, stock and package dimensions. When you publish, the product appears in the catalog right away, unless the administration has prior review turned on: then it appears once approved, and editing the content of a published product sends it back to review.", "titleFr": "Publiez vos produits", "bodyFr": "Ajoutez photos, description, attributs, variantes, prix, stock et dimensions du colis. À la publication, le produit apparaît immédiatement au catalogue, sauf si l’administration a activé la révision préalable : il s’affiche alors une fois approuvé, et modifier le contenu d’un produit publié le renvoie en révision.", "titleHt": "Pibliye pwodwi ou yo", "bodyHt": "Ajoute foto, deskripsyon, atribi, varyant, pri, stòk ak mezi pake a. Lè w pibliye, pwodwi a parèt nan katalòg la touswit, sof si administrasyon an aktive revizyon davans: lè sa a li parèt lè yo apwouve l, e si w modifye kontni yon pwodwi ki pibliye li retounen nan revizyon."}, {"title": "Elige a dónde envías", "body": "En cada producto, en «Destinos de envío», decides si se envía a todos los destinos de tu tienda, solo a algunos países o a todos excepto algunos. Los compradores de los países excluidos lo ven como «No disponible» y no pueden pagarlo.", "titleEn": "Choose where you ship", "bodyEn": "On each product, under “Shipping destinations”, you decide whether it ships to all of your store’s destinations, only to some countries or to all except some. Buyers in excluded countries see it as “Not available” and can’t pay for it.", "titleFr": "Choisissez où vous expédiez", "bodyFr": "Sur chaque produit, dans « Destinations de livraison », vous décidez s’il est expédié vers toutes les destinations de votre boutique, seulement vers certains pays ou vers tous sauf certains. Les acheteurs des pays exclus le voient « Non disponible » et ne peuvent pas le payer.", "titleHt": "Chwazi ki kote w voye", "bodyHt": "Sou chak pwodwi, nan « Destinasyon livrezon », ou deside si li ale nan tout destinasyon boutik ou, sèlman nan kèk peyi oswa nan tout sof kèk. Achtè nan peyi ou eskli yo wè l « Pa disponib » epi yo pa ka peye l."}, {"title": "Envía tus pedidos", "body": "Prepara los pedidos pagados en 1 a 3 días hábiles. Compra la etiqueta desde tu panel (se descuenta del envío que pagó el cliente) o despacha por tu cuenta y registra el número de seguimiento: en ese caso recibes lo que el cliente pagó por el envío.", "titleEn": "Ship your orders", "bodyEn": "Prepare paid orders within 1 to 3 business days. Buy the label from your dashboard (it is deducted from the shipping the customer paid) or ship on your own and enter the tracking number: in that case you receive what the customer paid for shipping.", "titleFr": "Expédiez vos commandes", "bodyFr": "Préparez les commandes payées en 1 à 3 jours ouvrables. Achetez l’étiquette depuis votre tableau de bord (elle est déduite de la livraison payée par le client) ou expédiez par vos propres moyens et saisissez le numéro de suivi : dans ce cas, vous recevez ce que le client a payé pour la livraison.", "titleHt": "Voye kòmand ou yo", "bodyHt": "Prepare kòmand ki peye yo nan 1 a 3 jou ouvrab. Achte etikèt la depi nan tablo bò w (yo retire l nan livrezon kliyan an te peye a) oswa voye pa pwòp mwayen w epi antre nimewo swivi a: nan ka sa a ou resevwa sa kliyan an te peye pou livrezon an."}, {"title": "Devoluciones", "body": "Todas las tiendas usan la política de devoluciones de NEXOVAX: 30 días desde la entrega, el cliente envía el producto por correo y paga el envío de vuelta, sin cargo por reposición y sin cambios. Revisa las solicitudes, recibe e inspecciona el producto; después se emite el reembolso.", "titleEn": "Returns", "bodyEn": "Every store uses the NEXOVAX return policy: 30 days from delivery, the customer sends the product back by mail and pays the return shipping, no restocking fee and no exchanges. Review the requests, receive and inspect the product; the refund is then issued.", "titleFr": "Retours", "bodyFr": "Toutes les boutiques appliquent la politique de retour de NEXOVAX : 30 jours après la livraison, le client renvoie le produit par la poste et paie le retour, sans frais de remise en stock ni échange. Examinez les demandes, recevez et inspectez le produit ; le remboursement est ensuite émis.", "titleHt": "Retou", "bodyHt": "Tout boutik yo itilize politik retou NEXOVAX: 30 jou apre livrezon an, kliyan an voye pwodwi a pa lapòs epi li peye livrezon retou a, san frè remete an stòk e san echanj. Revize demann yo, resevwa epi enspekte pwodwi a; apre sa ranbousman an fèt."}]}$h$::jsonb);
SELECT pg_temp.nx_set('help.commissions', $h${"body": "La plataforma cobra una comisión por venta sobre el valor de los productos (sin envío ni impuestos), configurada por la administración y visible en tu panel de finanzas. Los fondos de cada pedido pasan a tu saldo disponible una vez entregado el pedido y cumplido el periodo de retención, siempre que no tenga una devolución o reclamo abierto. Luego puedes solicitar un retiro a tu cuenta de cobro verificada.", "bodyEn": "The platform charges a commission per sale on the value of the products (excluding shipping and taxes), set by the administration and shown in your finance dashboard. Each order’s funds move to your available balance once the order is delivered and the holding period has passed, as long as it has no open return or claim. You can then request a payout to your verified payout account.", "bodyFr": "La plateforme prélève une commission par vente sur la valeur des produits (hors livraison et taxes), fixée par l’administration et visible dans votre tableau de bord financier. Les fonds de chaque commande passent à votre solde disponible une fois la commande livrée et la période de rétention écoulée, à condition qu’aucun retour ou litige ne soit ouvert. Vous pouvez ensuite demander un versement sur votre compte vérifié.", "bodyHt": "Platfòm nan pran yon komisyon sou chak vant sou valè pwodwi yo (san livrezon ni taks), administrasyon an fikse l epi li parèt nan tablo finans ou. Lajan chak kòmand pase nan balans disponib ou lè kòmand lan fin livre epi peryòd kenbe a fin pase, toutotan pa gen yon retou oswa yon reklamasyon ki louvri. Apre sa ou ka mande yon retrè sou kont peman ou ki verifye.", "showRate": true, "showPayoutMinimum": true}$h$::jsonb);
